function msOf(i){return F[i].h*1000/fps()}
function show(i){
  at=(i%n+n)%n;
  var f=F[at];
  img.src=f.s;
  if(cap)cap.textContent=f.n||"";
  count.textContent=D.words.frame+" "+(at+1)+" "+D.words.of+" "+n+(f.k?" \\u25c6":"");
  prev.disabled=!loopBox.checked&&at===0;
  next.disabled=!loopBox.checked&&at===n-1;
}
function stop(){running=false;clearTimeout(timer);play.textContent=D.words.play;play.setAttribute("aria-pressed","false")}
function tick(){
  if(!running)return;
  if(at===n-1&&!loopBox.checked){stop();return}
  show(at+1);
  schedule();
}
function schedule(){
  due+=msOf(at);
  var wait=due-Date.now();
  if(wait<0){due=Date.now();wait=0}
  timer=setTimeout(tick,wait);
}
function start(){
  if(n<2)return;
  if(at===n-1&&!loopBox.checked)show(0);
  running=true;play.textContent=D.words.pause;play.setAttribute("aria-pressed","true");
  due=Date.now();schedule();
}
function toggle(){if(running)stop();else start()}
play.addEventListener("click",toggle);
prev.addEventListener("click",function(){stop();show(at-1)});
next.addEventListener("click",function(){stop();show(at+1)});
fpsSel.addEventListener("change",function(){if(running){clearTimeout(timer);due=Date.now();schedule()}});
loopBox.addEventListener("change",function(){show(at)});
